import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"兌下離上 睽：","description":"京氏易傳 - 兌下離上 睽：","frontmatter":{"title":"兌下離上 睽：","description":"京氏易傳 - 兌下離上 睽："},"headers":[],"relativePath":"classics/jingshi/030.md","filePath":"classics/jingshi/030.md"}'),i={name:"classics/jingshi/030.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"兌下離上-睽",tabindex:"-1"},[l("兌下離上 睽： "),e("a",{class:"header-anchor",href:"#兌下離上-睽","aria-label":"Permalink to “兌下離上 睽：”"},"​")],-1),e("p",null,"火澤二象，氣運【一作轉。】非合。陰消陽長，取象何比。惟陽是從。陰陽動靜，剛柔分焉。先睽後合，其消通也。文明上照，幽暗分矣。【兌處下，為積陰暗之象也；離在上，為明照於下。】《易》雲：“見豕負塗，載鬼一車，先張之弧，後說之弧，往遇雨則吉。群疑亡也。”【先疑，暗也；後說，明也。】與離為飛伏。【己酉金，丙戌土。】諸侯立九四為世，初元士為應。",-1),e("p",null,"建始甲午至己亥，【芒種至小雪。】積算起己亥至戊戌。【水土入卦。】",-1),e("p",null,"五星從位起歲星，【歲木星入卦。】參宿從位降己酉，【二十八宿配參宿，入卦己酉土。】分氣候三十六。【起數積算。】",-1),e("p",null,"金火二運合土宮，配吉凶於歲時。六五陰柔處文明，九二四得立權臣。（虎易注：“九二四得立權臣”。疑為：“九四世得立權臣”之誤。）",-1),e("p",null,"陰陽相蕩，六位逆遷，變離入乾。健於外象，坎入履。（虎易注：“坎入履。”疑為“變入履”或“降入履”之誤。）【陰陽推遷，變化六爻。吉凶之兆，著於要之爻。如臣事君，近多憂也。】次降入天澤履卦。",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
